}

def compute_kstar(auc_list, theta):
    k = 0
    for auc in auc_list:
        if auc >= theta:
            k += 1
        else:
            break
    return k

for theta in [0.55, 0.60, 0.65, 0.70]:
    print(f'theta={theta:.2f}:')
    for name, aucs in AUC_DATA.items():
        k = compute_kstar(aucs, theta)
        print(f'  {name}: K*={k}')
    print()
